    private static readonly string[] _knownCategories = ["timeout", "deserialization", "authorization"];

    private List<DeadLetterEntry> _allEntries = [];
    private IReadOnlyList<DeadLetterEntry> _filteredEntries = [];
    private bool _isLoading = true;
    private bool _apiUnavailable;
    private bool _disposed;
    private string _apiErrorMessage = "The admin backend service may be unavailable. Check DAPR sidecar connectivity.";
    private string? _tenantFilter;
    private string? _tenantFilterInput;
    private string? _searchFilter;
    private string? _searchFilterInput;
    private Timer? _tenantDebounceTimer;
    private Timer? _searchDebounceTimer;
    private CancellationTokenSource? _loadCts;
    private bool _isOperating;
    private DeadLetterEntry? _expandedEntry;
    private HashSet<string> _selectedIds = [];
    private HashSet<string> _loadedMessageIds = [];
    private string? _continuationToken;
    private int _totalCount;
    private string? _failureCategory = "All";

    // Dialog state
    private bool _showRetryDialog;
    private FluentDialog? _retryDialog;
    private bool _pendingShowRetry;
    private bool _showSkipDialog;
    private FluentDialog? _skipDialog;
    private bool _pendingShowSkip;
    private bool _showArchiveDialog;
    private FluentDialog? _archiveDialog;
    private bool _pendingShowArchive;
    private int _bulkProgressCurrent;
    private int _bulkProgressTotal;
    private int _bulkActionAttempt;
    private BulkActionFailureState? _bulkActionFailure;
    private CancellationTokenSource? _bulkActionCts;
    private string? _bulkInitiatorId;

    private bool _isAnyDialogOpen => _showRetryDialog || _showSkipDialog || _showArchiveDialog;

    // Computed properties
    private int TenantsAffected => _allEntries.Select(e => e.TenantId).Distinct().Count();

    private int SelectedTenantCount => _allEntries
        .Where(entry => _selectedIds.Contains(entry.MessageId))
        .Select(entry => entry.TenantId)
        .Distinct(StringComparer.Ordinal)
        .Count();

    private string OldestEntryText => _allEntries.Count == 0
        ? "None"
        : TimeFormatHelper.FormatRelativeTime(_allEntries.Min(e => e.FailedAtUtc));

    private string OldestEntryTooltip => _allEntries.Count == 0
        ? "No entries"
        : _allEntries.Min(e => e.FailedAtUtc).ToString("u");

    private int HighRetryCount => _allEntries.Count(e => e.RetryCount >= 3);

    private bool? HeaderCheckState
    {
        get
        {
            if (_filteredEntries.Count == 0 || _selectedIds.Count == 0)
            {
                return false;
            }

            int selectedVisible = _filteredEntries.Count(e => _selectedIds.Contains(e.MessageId));
            if (selectedVisible == 0)
            {
                return false;
            }

            return selectedVisible == _filteredEntries.Count
                ? true
                : null;
        }
    }

    protected override async Task OnInitializedAsync()
    {
        ReadUrlParameters();
        _tenantFilterInput = _tenantFilter;
        _searchFilterInput = _searchFilter;
        await LoadDataAsync();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (_pendingShowRetry && _retryDialog is not null)
        {
            await _retryDialog.ShowAsync().ConfigureAwait(false);
            _pendingShowRetry = false;
        }

        if (_pendingShowSkip && _skipDialog is not null)
        {
            await _skipDialog.ShowAsync().ConfigureAwait(false);
            _pendingShowSkip = false;
        }

        if (_pendingShowArchive && _archiveDialog is not null)
        {
            await _archiveDialog.ShowAsync().ConfigureAwait(false);
            _pendingShowArchive = false;
        }
    }

    private async Task LoadDataAsync()
    {
        _loadCts?.Cancel();
        _loadCts = new CancellationTokenSource();
        CancellationToken ct = _loadCts.Token;

        _isLoading = _allEntries.Count == 0;
        _allEntries = [];
        _filteredEntries = [];
        _loadedMessageIds = [];
        _continuationToken = null;
        _totalCount = 0;
        _expandedEntry = null;

        try
        {
            PagedResult<DeadLetterEntry> result = await DeadLetterApi
                .GetDeadLettersAsync(_tenantFilter, 100, null, ct)
                .ConfigureAwait(false);
            foreach (DeadLetterEntry entry in result.Items)
            {
                if (_loadedMessageIds.Add(entry.MessageId))
                {
                    _allEntries.Add(entry);
                }
            }

            _totalCount = result.TotalCount;
            _continuationToken = result.ContinuationToken;
            UpdateFilteredEntries();
            _apiUnavailable = false;
            _apiErrorMessage = "The admin backend service may be unavailable. Check DAPR sidecar connectivity.";
        }
        catch (OperationCanceledException)
        {
            return;
        }
        catch (UnauthorizedAccessException)
        {
            _apiUnavailable = true;
            _apiErrorMessage = "Authentication required. Please sign in again.";
            UpdateFilteredEntries();
        }
        catch (ForbiddenAccessException)
        {
            _apiUnavailable = true;
            _apiErrorMessage = "Access denied. Insufficient permissions to view dead-letter entries.";
            UpdateFilteredEntries();
        }
        catch (HttpRequestException ex)
        {
            _apiUnavailable = true;
            _apiErrorMessage = $"Unable to load dead-letter entries ({(int?)ex.StatusCode ?? 0}).";
            UpdateFilteredEntries();
        }
        catch (ServiceUnavailableException)
        {
            _apiUnavailable = true;
            _apiErrorMessage = "The admin backend service may be unavailable. Check DAPR sidecar connectivity.";
            UpdateFilteredEntries();
        }
        finally
        {
            _isLoading = false;
            await InvokeAsync(StateHasChanged);
        }
    }

    private async Task LoadMoreAsync()
    {
        if (_continuationToken is null)
        {
            return;
        }

        _loadCts?.Cancel();
        _loadCts = new CancellationTokenSource();
        CancellationToken ct = _loadCts.Token;

        try
        {
            PagedResult<DeadLetterEntry> result = await DeadLetterApi
                .GetDeadLettersAsync(_tenantFilter, 100, _continuationToken, ct)
                .ConfigureAwait(false);
            foreach (DeadLetterEntry entry in result.Items)
            {
                if (_loadedMessageIds.Add(entry.MessageId))
                {
                    _allEntries.Add(entry);
                }
            }

            _totalCount = result.TotalCount;
            _continuationToken = result.ContinuationToken;
            UpdateFilteredEntries();
        }
        catch (OperationCanceledException)
        {
            return;
        }
        catch (Exception)
        {
            await ToastService.ShowErrorAsync("Failed to load more entries.");
        }
        finally
        {
            await InvokeAsync(StateHasChanged);
        }
    }

    private void UpdateFilteredEntries()
    {
        IEnumerable<DeadLetterEntry> filtered = _allEntries;

        if (string.Equals(_failureCategory, "Other", StringComparison.OrdinalIgnoreCase))
        {
            filtered = filtered.Where(e =>
                !_knownCategories.Any(cat =>
                    SafeFailureSearchText(e).Contains(cat, StringComparison.OrdinalIgnoreCase)));
        }
        else if (!string.IsNullOrWhiteSpace(_failureCategory)
            && !string.Equals(_failureCategory, "All", StringComparison.OrdinalIgnoreCase))
        {
            string category = _failureCategory;
            filtered = filtered.Where(e =>
                SafeFailureSearchText(e).Contains(category, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(_searchFilter))
        {
            string search = _searchFilter;
            filtered = filtered.Where(e =>
                e.OriginalCommandType.Contains(search, StringComparison.OrdinalIgnoreCase)
                || SafeFailureSearchText(e).Contains(search, StringComparison.OrdinalIgnoreCase));
        }

        _filteredEntries = filtered.ToList();
    }

    private async Task OnManualRefresh()
    {
        _selectedIds = [];
        await LoadDataAsync();
    }

    private void OnTenantFilterChanged()
    {
        _tenantDebounceTimer?.Dispose();
        _tenantDebounceTimer = new Timer(OnTenantDebounceElapsed, null, 300, Timeout.Infinite);
    }

    private void OnTenantDebounceElapsed(object? state)
    {
        if (_disposed)
        {
            return;
        }

        _ = InvokeAsync(async () =>
        {
            if (_disposed)
            {
                return;
            }

            _tenantFilter = string.IsNullOrWhiteSpace(_tenantFilterInput)
                ? null
                : _tenantFilterInput.Trim();
            _selectedIds = [];
            UpdateUrl();
            await LoadDataAsync();
        });
    }

    private void OnSearchFilterChanged()
    {
        _searchDebounceTimer?.Dispose();
        _searchDebounceTimer = new Timer(OnSearchDebounceElapsed, null, 300, Timeout.Infinite);
    }

    private void OnSearchDebounceElapsed(object? state)
    {
        if (_disposed)
        {
            return;
        }

        _ = InvokeAsync(() =>
        {
            if (_disposed)
            {
                return;
            }

            _searchFilter = string.IsNullOrWhiteSpace(_searchFilterInput)
                ? null
                : _searchFilterInput.Trim();
            _selectedIds = [];
            UpdateFilteredEntries();
            UpdateUrl();
            StateHasChanged();
        });
    }

    private void OnCategoryChanged()
    {
        if (string.Equals(_failureCategory, "All", StringComparison.OrdinalIgnoreCase))
        {
            _searchFilterInput = null;
            _searchFilter = null;
        }
        else if (string.Equals(_failureCategory, "Other", StringComparison.OrdinalIgnoreCase))
        {
            _searchFilterInput = "other";
            _searchFilter = null;
        }
        else
        {
            _searchFilterInput = _failureCategory?.ToLowerInvariant();
            _searchFilter = _searchFilterInput;
        }

        _selectedIds = [];
        UpdateFilteredEntries();
        UpdateUrl();
    }

    private void ReadUrlParameters()
    {
        Uri uri = NavigationManager.ToAbsoluteUri(NavigationManager.Uri);
        System.Collections.Specialized.NameValueCollection query = System.Web.HttpUtility.ParseQueryString(uri.Query);
        _tenantFilter = query["tenant"];
        _searchFilter = query["search"];
        string? category = query["category"];
        if (!string.IsNullOrEmpty(category))
        {
            _failureCategory = category;
            if (string.Equals(category, "Other", StringComparison.OrdinalIgnoreCase))
            {
                _searchFilter = null;
            }
            else if (!string.Equals(category, "All", StringComparison.OrdinalIgnoreCase))
            {
                _searchFilter = category.ToLowerInvariant();
            }
        }
    }

    private void UpdateUrl()
    {
        List<string> queryParams = [];
        if (!string.IsNullOrEmpty(_tenantFilter))
        {
            queryParams.Add($"tenant={Uri.EscapeDataString(_tenantFilter)}");
        }

        if (!string.IsNullOrEmpty(_searchFilter))
        {
            queryParams.Add($"search={Uri.EscapeDataString(_searchFilter)}");
        }

        if (!string.IsNullOrEmpty(_failureCategory) && !string.Equals(_failureCategory, "All", StringComparison.OrdinalIgnoreCase))
        {
            queryParams.Add($"category={Uri.EscapeDataString(_failureCategory)}");
        }

        string url = queryParams.Count > 0
            ? $"/health/dead-letters?{string.Join('&', queryParams)}"
            : "/health/dead-letters";
        NavigationManager.NavigateTo(url, forceLoad: false, replace: true);
    }

    private void OnRowClick(DeadLetterEntry? entry)
    {
        if (entry is null)
        {
            _expandedEntry = null;
            return;
        }

        _expandedEntry = _expandedEntry == entry ? null : entry;
    }

    // Selection
    private void OnHeaderCheckStateChanged(bool? checkState)
    {
        bool isChecked = checkState == true;
        if (isChecked)
        {
            foreach (DeadLetterEntry entry in _filteredEntries)
            {
                _ = _selectedIds.Add(entry.MessageId);
            }
        }
        else
        {
            foreach (DeadLetterEntry entry in _filteredEntries)
            {
                _ = _selectedIds.Remove(entry.MessageId);
            }
        }
    }

    private void OnRowCheckChanged(string messageId, bool selected)
    {
        if (selected)
        {
            _ = _selectedIds.Add(messageId);
        }
        else
        {
            _ = _selectedIds.Remove(messageId);
        }
    }

    // Bulk action dialogs
    private void OpenBulkDialog(string action)
    {
        if (_isAnyDialogOpen) { return; }
        _bulkActionFailure = null;
        if (string.Equals(action, "retry", StringComparison.OrdinalIgnoreCase))
        {
            _bulkInitiatorId = "dead-letter-retry-selected";
            _showRetryDialog = true;
            _pendingShowRetry = true;
        }
        else if (string.Equals(action, "skip", StringComparison.OrdinalIgnoreCase))
        {
            _bulkInitiatorId = "dead-letter-skip-selected";
            _showSkipDialog = true;
            _pendingShowSkip = true;
        }
        else if (string.Equals(action, "archive", StringComparison.OrdinalIgnoreCase))
        {
            _bulkInitiatorId = "dead-letter-archive-selected";
            _showArchiveDialog = true;
            _pendingShowArchive = true;
        }
    }

    private async Task CloseRetryDialogAsync()
    {
        if (_isOperating) { return; }
        if (_retryDialog is not null) { await _retryDialog.HideAsync().ConfigureAwait(false); }
        _showRetryDialog = false;
        await RestoreBulkInitiatorFocusAsync().ConfigureAwait(false);
    }

    private async Task CloseSkipDialogAsync()
    {
        if (_isOperating) { return; }
        if (_skipDialog is not null) { await _skipDialog.HideAsync().ConfigureAwait(false); }
        _showSkipDialog = false;
        await RestoreBulkInitiatorFocusAsync().ConfigureAwait(false);
    }

    private async Task CloseArchiveDialogAsync()
    {
        if (_isOperating) { return; }
        if (_archiveDialog is not null) { await _archiveDialog.HideAsync().ConfigureAwait(false); }
        _showArchiveDialog = false;
        await RestoreBulkInitiatorFocusAsync().ConfigureAwait(false);
    }

    private async Task OnRetryConfirm() =>
        await ExecuteBulkActionAsync("retry", (tenantId, ids, ct) => DeadLetterApi.RetryDeadLettersAsync(tenantId, ids, ct));

    private async Task OnSkipConfirm() =>
        await ExecuteBulkActionAsync("skip", (tenantId, ids, ct) => DeadLetterApi.SkipDeadLettersAsync(tenantId, ids, ct));

    private async Task OnArchiveConfirm() =>
        await ExecuteBulkActionAsync("archive", (tenantId, ids, ct) => DeadLetterApi.ArchiveDeadLettersAsync(tenantId, ids, ct));

    private async Task ExecuteBulkActionAsync(
        string actionName,
        Func<string, IReadOnlyList<string>, CancellationToken, Task<AdminOperationResult?>> apiCall)
    {
        if (_isOperating || _disposed)
        {
            return;
        }

        int attempt = ++_bulkActionAttempt;
        _bulkActionCts?.Cancel();
        _bulkActionCts?.Dispose();
        _bulkActionCts = new CancellationTokenSource();
        CancellationToken ct = _bulkActionCts.Token;
        _isOperating = true;
        _bulkActionFailure = null;
        StateHasChanged();

        IReadOnlyList<DeadLetterEntry> matchedEntries = _allEntries
            .Where(e => _selectedIds.Contains(e.MessageId))
            .ToList();

        if (_selectedIds.Count == 0 || matchedEntries.Count != _selectedIds.Count)
        {
            string message = matchedEntries.Count == 0
                ? "No selected dead-letter commands are available to submit."
                : "Some selected dead-letter commands are no longer available. Review the selection and try again.";
            await ToastService.ShowErrorAsync(message).ConfigureAwait(false);
            await CloseAllDialogsAsync().ConfigureAwait(false);
            await RestoreBulkInitiatorFocusAsync().ConfigureAwait(false);
            _isOperating = false;
            await InvokeAsync(StateHasChanged);
            return;
        }

        IReadOnlyList<IGrouping<string, DeadLetterEntry>> tenantGroups = matchedEntries
            .GroupBy(e => e.TenantId)
            .ToList();

        _bulkProgressTotal = tenantGroups.Count;
        _bulkProgressCurrent = 0;

        int successCount = 0;
        int failCount = 0;
        bool denied = false;
        List<BulkActionFailureItem> failures = [];

        try
        {
            for (int groupIndex = 0; groupIndex < tenantGroups.Count; groupIndex++)
            {
                IGrouping<string, DeadLetterEntry> group = tenantGroups[groupIndex];
                _bulkProgressCurrent++;
                StateHasChanged();

                try
                {
                    AdminOperationResult? result = await apiCall(
                        group.Key,
                        group.Select(e => e.MessageId).ToList(),
                        ct);

                    if (result?.Success == true)
                    {
                        successCount += group.Count();
                    }
                    else
                    {
                        failCount += group.Count();
                        failures.Add(BulkActionFailureItem.FromResult(actionName, group.Key, group.Select(e => e.MessageId), result));
                    }
                }
                catch (Exception ex) when (ex is UnauthorizedAccessException or ForbiddenAccessException)
                {
                    denied = true;
                    failCount += group.Count();
                    failures.Add(BulkActionFailureItem.FromException(actionName, group.Key, group.Select(e => e.MessageId), ex));
                    foreach (IGrouping<string, DeadLetterEntry> unattemptedGroup in tenantGroups.Skip(groupIndex + 1))
                    {
                        failCount += unattemptedGroup.Count();
                        failures.Add(BulkActionFailureItem.FromUnattempted(
                            actionName,
                            unattemptedGroup.Key,
                            unattemptedGroup.Select(e => e.MessageId)));
                    }

                    break;
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    failCount += group.Count();
                    failures.Add(BulkActionFailureItem.FromException(actionName, group.Key, group.Select(e => e.MessageId), ex));
                }
            }

            if (_disposed || attempt != _bulkActionAttempt)
            {
                return;
            }

            // Report results
            string capitalizedAction = char.ToUpperInvariant(actionName[0]) + actionName[1..];
            if (failCount == 0)
            {
                // Full success
                await ToastService.ShowSuccessAsync(
                    $"{capitalizedAction} request accepted for {successCount} dead-letter command(s).").ConfigureAwait(false);
                _selectedIds = [];
                await CloseAllDialogsAsync().ConfigureAwait(false);
                await LoadDataAsync().ConfigureAwait(false);
            }
            else if (successCount > 0)
            {
                // Partial failure
                BulkActionFailureState failureState = BulkActionFailureState.Create(actionName, failures);
                _selectedIds = failures
                    .SelectMany(f => f.MessageIds)
                    .Distinct(StringComparer.Ordinal)
                    .ToHashSet(StringComparer.Ordinal);
                string failedIds = BuildFailedMessageSummary(_selectedIds);
                await ToastService.ShowWarningAsync(
                    $"{capitalizedAction} request accepted for {successCount} commands. {failCount} were not accepted: {failureState.Message}. {failedIds}").ConfigureAwait(false);
                await CloseAllDialogsAsync().ConfigureAwait(false);
                await LoadDataAsync().ConfigureAwait(false);
                if (denied)
                {
                    await RestoreBulkInitiatorFocusAsync().ConfigureAwait(false);
                }
            }
            else
            {
                // Full failure — stay on dialog, keep selection
                BulkActionFailureState failureState = BulkActionFailureState.Create(actionName, failures);
                if (!_disposed && attempt == _bulkActionAttempt)
                {
                    _bulkActionFailure = failureState;
                }

                await ToastService.ShowErrorAsync($"Failed to {actionName} entries: {failureState.Message}");
                if (denied)
                {
                    await CloseAllDialogsAsync().ConfigureAwait(false);
                    await RestoreBulkInitiatorFocusAsync().ConfigureAwait(false);
                }
            }
        }
        catch (OperationCanceledException)
        {
            return;
        }
        finally
        {
            if (!_disposed && attempt == _bulkActionAttempt)
            {
                _isOperating = false;
                // Post-await completion path: continuation may resume off the renderer dispatcher.
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    private async Task CloseAllDialogsAsync()
    {
        if (_retryDialog is not null && _showRetryDialog) { await _retryDialog.HideAsync().ConfigureAwait(false); }
        if (_skipDialog is not null && _showSkipDialog) { await _skipDialog.HideAsync().ConfigureAwait(false); }
        if (_archiveDialog is not null && _showArchiveDialog) { await _archiveDialog.HideAsync().ConfigureAwait(false); }
        _showRetryDialog = false;
        _showSkipDialog = false;
        _showArchiveDialog = false;
        _bulkActionFailure = null;
    }

    private async Task RestoreBulkInitiatorFocusAsync()
    {
        string? focusId = _bulkInitiatorId;
        _bulkInitiatorId = null;
        await InvokeAsync(StateHasChanged).ConfigureAwait(false);
        await FocusService.RestoreAsync(focusId).ConfigureAwait(false);
    }

    // Helpers
    private static string Truncate(string value, int maxLength) =>
        value.Length <= maxLength ? value : value[..maxLength];

    private static string SafeFailureText(DeadLetterEntry entry)
        => entry.Failure is null
            ? entry.FailureReason ?? string.Empty
            : $"{entry.Failure.Placeholder} ReasonCode={entry.Failure.ReasonCode}; Stage={entry.Failure.Stage}; Content={entry.Failure.ContentKind}.";

    private static string SafeFailureSearchText(DeadLetterEntry entry)
        => entry.Failure is null
            ? entry.FailureReason ?? string.Empty
            : string.Join(' ', entry.Failure.ContentKind, entry.Failure.ReasonCode, entry.Failure.Stage, entry.Failure.SafeNextAction);

    private static string GetShortTypeName(string fullTypeName)
    {
        int lastDot = fullTypeName.LastIndexOf('.');
        return lastDot >= 0 ? fullTypeName[(lastDot + 1)..] : fullTypeName;
    }

    private bool ShouldShowFailure(string actionName) =>
        _bulkActionFailure is not null
        && string.Equals(_bulkActionFailure.ActionName, actionName, StringComparison.OrdinalIgnoreCase);

    private static string Sanitize(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return "Unavailable";
        }

        string sanitized = value;
        string[] blockedMarkers =
        [
            "bearer ",
            "signingkey",
            "signing key",
            "redis://",
            "redis ",
            "connectionstring",
            "connection string",
            "data source=",
            "server=",
            "host=",
            "user id=",
            "password=",
            "secret",
            " at ",
            ".internal",
        ];
        foreach (string marker in blockedMarkers)
        {
            int index = sanitized.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
            if (index >= 0)
            {
                sanitized = sanitized[..index] + "[redacted]";
                break;
            }
        }

        return sanitized.Length <= 240 ? sanitized : sanitized[..240] + "...";
    }

    private static string BuildFailedMessageSummary(IEnumerable<string> messageIds)
    {
        string[] ids = messageIds.Take(4).Select(id => Truncate(Sanitize(id), 80)).ToArray();
        string summary = ids.Length == 0
            ? "Failed message IDs are unavailable."
            : $"Failed message IDs: {string.Join(", ", ids)}.";
        return summary.Length <= 240 ? summary : summary[..240] + "...";
    }

    private sealed record BulkActionFailureState(string ActionName, string Title, string Message, IReadOnlyList<(string Label, string Value)> Details)
    {
        public static BulkActionFailureState Create(string actionName, IReadOnlyList<BulkActionFailureItem> failures)
        {
            string action = char.ToUpperInvariant(actionName[0]) + actionName[1..];
            string message = failures.LastOrDefault()?.Message ?? $"Failed to {actionName} selected entries.";
            List<(string Label, string Value)> details =
            [
                ("Action", action),
                ("Tenants", string.Join(", ", failures.Select(f => f.TenantId).Distinct())),
                ("Message IDs", string.Join(", ", failures.SelectMany(f => f.MessageIds).Distinct())),
            ];

            string? status = failures.Select(f => f.Status).FirstOrDefault(s => !string.IsNullOrWhiteSpace(s));
            if (!string.IsNullOrWhiteSpace(status)) { details.Add(("Status", status)); }
            string? errorCode = failures.Select(f => f.ErrorCode).FirstOrDefault(s => !string.IsNullOrWhiteSpace(s));
            if (!string.IsNullOrWhiteSpace(errorCode)) { details.Add(("Error Code", errorCode)); }
            string? operationId = failures.Select(f => f.OperationId).FirstOrDefault(s => !string.IsNullOrWhiteSpace(s));
            if (!string.IsNullOrWhiteSpace(operationId)) { details.Add(("Operation ID", operationId)); }
            string? traceId = failures.Select(f => f.TraceId).FirstOrDefault(s => !string.IsNullOrWhiteSpace(s));
            if (!string.IsNullOrWhiteSpace(traceId)) { details.Add(("Trace ID", traceId)); }

            return new BulkActionFailureState(actionName, $"{action} failed", Sanitize(message), details.Select(d => (d.Label, Sanitize(d.Value))).ToList());
        }
    }

    private sealed record BulkActionFailureItem(
        string TenantId,
        IReadOnlyList<string> MessageIds,
        string Message,
        string? Status,
        string? ErrorCode,
        string? OperationId,
        string? TraceId)
    {
        public static BulkActionFailureItem FromResult(
            string actionName,
            string tenantId,
            IEnumerable<string> messageIds,
            AdminOperationResult? result) =>
            new(
                tenantId,
                messageIds.ToList(),
                result?.Message ?? $"Failed to {actionName} entries.",
                null,
                result?.ErrorCode,
                result?.OperationId,
                null);

        public static BulkActionFailureItem FromException(
            string actionName,
            string tenantId,
            IEnumerable<string> messageIds,
            Exception exception)
        {
            if (exception is AdminApiProblemException problem)
            {
                return new(
                    tenantId,
                    messageIds.ToList(),
                    problem.Detail ?? problem.Message,
                    problem.StatusCode is null ? null : $"{(int)problem.StatusCode} {problem.StatusCode}",
                    problem.ErrorCode,
                    problem.OperationId,
                    problem.TraceId);
            }

            return new(
                tenantId,
                messageIds.ToList(),
                exception.Message,
                exception is HttpRequestException http && http.StatusCode is not null ? $"{(int)http.StatusCode} {http.StatusCode}" : null,
                null,
                null,
                null);
        }

        public static BulkActionFailureItem FromUnattempted(
            string actionName,
            string tenantId,
            IEnumerable<string> messageIds) =>
            new(
                tenantId,
                messageIds.ToList(),
                $"Unable to {actionName} entries because authorization was denied for an earlier tenant group.",
                null,
                null,
                null,
                null);
    }

    public async ValueTask DisposeAsync()
    {
        _disposed = true;
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _bulkActionCts?.Cancel();
        _bulkActionCts?.Dispose();
        if (_tenantDebounceTimer is not null)
        {
            await _tenantDebounceTimer.DisposeAsync();
        }

        if (_searchDebounceTimer is not null)
        {
            await _searchDebounceTimer.DisposeAsync();
        }
    }

